mapper.select:
SELECT 
FROM fin_ex_route_memory_t
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND session_id = #{sessionId}
  AND item_type = 'ROUTE'
  AND status = 'ACTIVE'
ORDER BY created_at DESC
LIMIT #{limit}

SELECT 
FROM fin_ex_route_memory_t
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND session_id = #{sessionId}
  AND item_type = 'CLARIFY'
  AND status = 'ACTIVE'
ORDER BY created_at ASC

SELECT CASE WHEN EXISTS (
    SELECT 1
    FROM (
        SELECT intent_id, intent_name, domain_agent_id, source_run_id
        FROM fin_ex_route_memory_t
        WHERE tenant_id = #{tenantId}
          AND user_id = #{userId}
          AND session_id = #{sessionId}
          AND item_type = 'ROUTE'
          AND status = 'ACTIVE'
        ORDER BY created_at DESC, id DESC
        LIMIT 1
    ) latest
    JOIN fin_ex_chat_run_t r
      ON r.id = latest.source_run_id
     AND r.tenant_id = #{tenantId}
     AND r.user_id = #{userId}
     AND r.session_id = #{sessionId}
    WHERE r.status = 'COMPLETED'
      AND latest.domain_agent_id IS NULL
      AND (
            latest.intent_id = 'relay'
         OR latest.intent_name = 'no_match'
      )
) THEN TRUE ELSE FALSE END

